-- AI Assistance Disclosure:
-- Tool: Claude Code (model: Claude Opus 5.5), date: 2026-11-10
-- Scope: Implementation of SQL queries.
-- Author review: Reviewed, validated, and tested by the authors.

-- Every SQL statement chat-service runs, generated by sqlc into
-- internal/database/chatgen. Only internal/store calls the generated code.

-- name: LockErrand :exec
-- LockErrand makes one errand's events apply one at a time, even across
-- copies of the service. It holds until the transaction ends, so it only
-- works inside one.
SELECT pg_advisory_xact_lock(hashtextextended(sqlc.arg(errand_id)::uuid::text, 0));

-- name: UpsertRoomOnAccept :one
-- UpsertRoomOnAccept creates the room for errand.accepted. A repeat of the
-- event changes nothing. If errand.withdrawn arrived first and created the
-- room (EnsureRoom), it only fills in opened_version; the room stays ended.
-- inserted is true only when this call created the row.
INSERT INTO chat_rooms (errand_id, requester_id, courier_id, opened_version)
VALUES (@errand_id, @requester_id, @courier_id, sqlc.arg(opened_version)::integer)
ON CONFLICT (errand_id, courier_id) DO UPDATE
SET opened_version = COALESCE(chat_rooms.opened_version, EXCLUDED.opened_version)
RETURNING id, errand_id, requester_id, courier_id, opened_version,
          ended_at, end_reason, closes_at, created_at,
          (xmax = 0)::boolean AS inserted;

-- name: EnsureRoom :exec
-- EnsureRoom creates the room for errand.withdrawn when errand.accepted has
-- not arrived yet (opened_version stays NULL). An existing room is left alone.
INSERT INTO chat_rooms (errand_id, requester_id, courier_id)
VALUES (@errand_id, @requester_id, @courier_id)
ON CONFLICT (errand_id, courier_id) DO NOTHING;

-- name: EndRoom :one
-- EndRoom keeps the earliest ending: a repeated or later event changes
-- nothing and returns no row.
UPDATE chat_rooms
SET ended_at = sqlc.arg(ended_at)::timestamptz,
    end_reason = sqlc.arg(end_reason)::text,
    closes_at = sqlc.arg(closes_at)::timestamptz
WHERE id = @id AND (ended_at IS NULL OR ended_at > sqlc.arg(ended_at)::timestamptz)
RETURNING *;

-- name: EndRoomsForErrand :many
-- EndRoomsForErrand is EndRoom for every room of an errand (completed or
-- refunded). It returns only the rooms it changed.
UPDATE chat_rooms
SET ended_at = sqlc.arg(ended_at)::timestamptz,
    end_reason = sqlc.arg(end_reason)::text,
    closes_at = sqlc.arg(closes_at)::timestamptz
WHERE errand_id = @errand_id AND (ended_at IS NULL OR ended_at > sqlc.arg(ended_at)::timestamptz)
RETURNING *;

-- name: GetErrandEnding :one
SELECT * FROM errand_endings WHERE errand_id = @errand_id;

-- name: InsertErrandEnding :exec
-- InsertErrandEnding remembers that an errand completed or was refunded, so
-- a late errand.accepted creates its room already ended. Like EndRoom, it
-- keeps the earliest ending.
INSERT INTO errand_endings (errand_id, reason, ended_at)
VALUES (@errand_id, @reason, @ended_at)
ON CONFLICT (errand_id) DO UPDATE
SET reason = EXCLUDED.reason, ended_at = EXCLUDED.ended_at
WHERE errand_endings.ended_at > EXCLUDED.ended_at;

-- name: GetRoom :one
SELECT * FROM chat_rooms WHERE id = @id;

-- name: GetRoomByAssignment :one
SELECT * FROM chat_rooms WHERE errand_id = @errand_id AND courier_id = @courier_id;

-- name: ListRoomsForErrandAndUser :many
-- ListRoomsForErrandAndUser returns the caller's rooms for one errand, newest
-- first: at most one for a courier, one per accepting courier for the
-- requester.
SELECT * FROM chat_rooms
WHERE errand_id = @errand_id
  AND (requester_id = @user_id OR courier_id = @user_id)
ORDER BY created_at DESC, id;

-- name: ListRoomsForUser :many
-- ListRoomsForUser returns the caller's rooms on every errand, newest first.
SELECT * FROM chat_rooms
WHERE requester_id = @user_id OR courier_id = @user_id
ORDER BY created_at DESC, id
LIMIT @row_limit;

-- name: ListRoomsForErrand :many
-- ListRoomsForErrand returns every room of an errand, oldest first, including
-- withdrawn couriers' rooms. No route exposes it; tests use it to inspect rooms.
SELECT * FROM chat_rooms
WHERE errand_id = @errand_id
ORDER BY created_at, id;

-- name: InsertMessage :one
-- InsertMessage returns no row when the room already has a message with this
-- client_msg_id (a retried send); load that one with GetMessageByClientID.
INSERT INTO chat_messages (room_id, sender_id, body, client_msg_id)
VALUES (@room_id, @sender_id, @body, @client_msg_id)
ON CONFLICT (room_id, client_msg_id) DO NOTHING
RETURNING *;

-- name: GetMessageByClientID :one
SELECT * FROM chat_messages WHERE room_id = @room_id AND client_msg_id = @client_msg_id;

-- name: ListMessagesAfter :many
-- ListMessagesAfter is the catch-up page: messages newer than after_id,
-- oldest first.
SELECT * FROM chat_messages
WHERE room_id = @room_id AND id > @after_id
ORDER BY id
LIMIT @row_limit;

-- name: ListMessagesBefore :many
-- ListMessagesBefore is the scroll-back page: messages older than before_id,
-- NEWEST first so LIMIT keeps the closest ones. The store reverses them.
SELECT * FROM chat_messages
WHERE room_id = @room_id AND id < @before_id
ORDER BY id DESC
LIMIT @row_limit;

-- name: ListLastMessages :many
-- ListLastMessages returns the newest message of each listed room that has
-- any, for the room list.
SELECT DISTINCT ON (room_id) *
FROM chat_messages
WHERE room_id = ANY(@room_ids::uuid[])
ORDER BY room_id, id DESC;
